INSERT INTO trivia_facts (category, title, body, source) VALUES ('Blood types', 'O negative is the universal red cell type', 'Red cells from O negative donors can be given to patients of any blood type, which is why O negative blood is so often used in emergencies.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Blood types', 'AB positive is the universal plasma type', 'Plasma from AB donors can be given to patients of any blood type.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Blood types', 'O positive is the most common blood type', 'More people have O positive blood than any other type, so hospitals need a steady supply of it.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Blood types', 'AB negative is one of the rarest types', 'Only about 1% of people in the U.S. have AB negative blood.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Blood types', 'You inherit your blood type', 'Your ABO type and your Rh factor (positive or negative) are passed down from your biological parents.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Blood types', 'Blood is more than one thing', 'A donation can be separated into red cells, plasma and platelets, and each part can help a different patient.', 'World Health Organization (WHO)');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Donation tips', 'Wait 8 weeks between whole blood donations', 'Donors need to wait at least 56 days (8 weeks) between whole blood donations so the body can recover. This is the same gap used for the ''next eligible'' date in this app.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Donation tips', 'Drink water and eat well beforehand', 'Have a healthy meal and drink plenty of fluids before you donate, and keep drinking afterwards.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Donation tips', 'Eat iron-rich foods', 'Foods like red meat, fish, poultry, beans, spinach and iron-fortified cereals help keep your iron levels up.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Donation tips', 'The donation itself is quick', 'Giving whole blood usually takes about 8 to 10 minutes. The whole visit, including the health check and snack, takes around an hour.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Donation tips', 'One donation can help up to three people', 'Because blood is separated into parts, a single donation can help several patients.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Donation tips', 'Bring ID and get some rest', 'Bring a form of identification and try to get a good night''s sleep before your appointment.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Myths', 'Myth: donating blood is very painful', 'Most donors only feel a quick pinch when the needle goes in.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Myths', 'Myth: you can catch a disease by donating', 'A new, sterile needle is used for every donor and thrown away afterwards, so you cannot get an infection from donating.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Myths', 'Myth: donating leaves you weak for days', 'Your body replaces the fluid you gave within about 24 hours and the red cells within a few weeks. Most people feel fine after resting and drinking fluids.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Myths', 'Myth: I''m too old to donate', 'In many places there is no fixed upper age limit as long as you are healthy and meet the requirements. Rules vary, so check with your local blood service.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Myths', 'Myth: a tattoo means I can never donate', 'Usually it only means a waiting period, and the rules differ between countries and blood services. Ask your local blood service before you assume.', 'American Red Cross');
INSERT INTO trivia_facts (category, title, body, source) VALUES ('Myths', 'Myth: blood is only needed after disasters', 'Blood is needed every day, for surgery, childbirth complications, cancer treatment and accidents.', 'World Health Organization (WHO)');
